import fs from 'fs';
import os from 'os';
import path from 'path';
import { AgentVariantsError } from './errors';
import { staticPreviewPagePath } from '../utils/staticPreviewPage';
import type { StaticPreviewRecord } from './WorkspaceInventory';
import type { ProjectEnvironment } from './variant-project-runtime';
import { copyStaticPreviewDirectory } from './variantWorkspaceFiles';
import {
  isPathStrictlyInsideRoot,
  isPathWithinRoot,
} from '../utils/pathContainment';

const HISTORY_ENTRY_BOUNDARY_MESSAGE =
  'Cannot adopt past variant: entry and site root must stay inside its files directory.';

export const prepareStaticPreviewProjectFiles = ({
  sourceDir,
  entryPath,
  isWebsite,
}: {
  sourceDir: string;
  entryPath: string;
  isWebsite?: boolean;
}): string[] => {
  const entryFile = path.resolve(sourceDir, entryPath);
  if (!isPathStrictlyInsideRoot(sourceDir, entryFile))
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      'Artifact entry must be inside its project directory.',
    );
  const isEntryMapped =
    !isWebsite && entryFile !== path.join(sourceDir, 'index.html');
  if (isEntryMapped) {
    fs.mkdirSync(path.dirname(entryFile), { recursive: true });
    fs.copyFileSync(path.join(sourceDir, 'index.html'), entryFile);
  }
  return fs
    .readdirSync(sourceDir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) =>
      path
        .relative(sourceDir, path.join(entry.parentPath, entry.name))
        .split(path.sep)
        .join('/'),
    )
    .filter((file) => !isEntryMapped || file !== 'index.html');
};

export const stageStaticPreviewFiles = ({
  preview,
  workItemId,
  environment,
  isWebsite,
  briefMarkdown,
}: {
  preview: StaticPreviewRecord;
  workItemId: string;
  environment?: ProjectEnvironment;
  isWebsite: boolean;
  briefMarkdown?: string;
}): { rootPath: string; entryPath: string } => {
  const rootPath = fs.mkdtempSync(
    path.join(os.tmpdir(), `rivet-variant-${workItemId}-`),
  );
  const siteDirectory =
    isWebsite && environment?.framework === 'static' && environment.entryPath
      ? path.dirname(environment.entryPath)
      : '.';
  try {
    if (
      path.isAbsolute(siteDirectory) ||
      !isPathWithinRoot(rootPath, path.join(rootPath, siteDirectory))
    )
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        'Static website entry must stay inside its project.',
      );
    copyStaticPreviewDirectory(
      preview.assetBase,
      path.join(rootPath, siteDirectory),
    );
    if (briefMarkdown !== undefined)
      fs.writeFileSync(path.join(rootPath, 'brief.md'), briefMarkdown, 'utf8');
    return {
      rootPath,
      entryPath: path.join(siteDirectory, preview.entryPath),
    };
  } catch (error) {
    fs.rmSync(rootPath, { recursive: true, force: true });
    throw error;
  }
};

export const writeStaticPreviewPage = ({
  assetBase,
  html,
  source,
  previewRoutes,
}: {
  assetBase: string;
  html: string;
  source?: StaticPreviewRecord;
  previewRoutes?: string[];
}): string => {
  const entryPath = previewRoutes?.length
    ? (source?.entryPath ?? 'index.html')
    : 'index.html';
  const pagePath = staticPreviewPagePath({
    entryPath,
    routePath: previewRoutes?.[0],
  });
  const pageFile = path.join(assetBase, pagePath);
  fs.mkdirSync(path.dirname(pageFile), { recursive: true });
  fs.writeFileSync(pageFile, html, 'utf8');
  return entryPath;
};

export const resolveStaticPreviewFiles = async ({
  filesDir,
  entryPath,
  isWebsite,
}: {
  filesDir: string;
  entryPath: string;
  isWebsite: boolean;
}): Promise<{ assetBase: string; entryPath: string; hasAssets: boolean }> => {
  let assetBase: string;
  try {
    const filesRoot = await fs.promises.realpath(filesDir);
    const entryFile = path.resolve(filesRoot, entryPath);
    if (
      path.isAbsolute(entryPath) ||
      !isPathStrictlyInsideRoot(filesRoot, entryFile)
    )
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        HISTORY_ENTRY_BOUNDARY_MESSAGE,
      );
    const resolvedEntry = await fs.promises.realpath(entryFile);
    assetBase = await fs.promises.realpath(
      isWebsite ? path.dirname(entryFile) : filesRoot,
    );
    if (
      !isPathWithinRoot(filesRoot, assetBase) ||
      !isPathStrictlyInsideRoot(filesRoot, resolvedEntry)
    )
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        HISTORY_ENTRY_BOUNDARY_MESSAGE,
      );
    if (!(await fs.promises.stat(resolvedEntry)).isFile())
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        'Cannot adopt past variant: entry must be a regular file.',
      );
    await fs.promises.access(resolvedEntry, fs.constants.R_OK);
  } catch (error) {
    if (error instanceof AgentVariantsError) throw error;
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      'Cannot adopt past variant: no readable ' +
        entryPath +
        ' under ' +
        filesDir,
    );
  }
  const previewEntryPath = isWebsite ? path.basename(entryPath) : entryPath;
  let hasAssets = false;
  try {
    hasAssets = fs
      .readdirSync(assetBase)
      .some((name) => name !== previewEntryPath);
  } catch {
    hasAssets = false;
  }
  return { assetBase, entryPath: previewEntryPath, hasAssets };
};
